    parentName: "p",
    "href": "https://product.kyobobook.co.kr/detail/S000201621499"
  }, "\uAD6C\uC758 \uC99D\uBA85"), "\uC758 \"\uB2F4\"\uC740 \uC774\uBAA8\uC5D0\uAC8C \uC5B4\uB460\uC774 \uBB34\uC5C7\uC774\uB0D0\uACE0 \uBB3B\uB294\uB2E4. \uC774\uBAA8\uB294 \uCD5C\uB300\uD55C \uC124\uBA85\uD558\uB2E4 \uD654\uB97C \uB0B4\uBA70 \"\uB354 \uC0B4\uB2E4\uBCF4\uBA74 \uC790\uC5F0\uC2A4\uB7FD\uAC8C \uC54C\uAC8C \uB418\uB294\uB370 \uC9C0\uAE08 \uC774\uD574\uD560 \uC218 \uC5C6\uB2E4\uACE0 \uBB3B\uACE0 \uB610 \uBB3C\uC5B4\uBD24\uC790 \uC774\uD574\uD558\uC9C0 \uBABB\uD560 \uAC70\uB77C\uACE0.\" \uB2E8\uC815\uC9D3\uB294\uB2E4."), mdx("p", null, "\uC774\uD574\uD558\uC9C0 \uBABB\uD588\uB358 \uB2F4\uC740 \"\uB0B4\uAC00 \uC9C0\uAE08 \uC8FD\uC5B4\uBC84\uB9AC\uBA74 \uADF8\uAC74 \uC601\uC601 \uBAA8\uB974\uB294\uAC8C \uB418\uB294 \uAC70\uC796\uC544!\" \uB77C\uBA70 \uD654\uB97C \uB0B8\uB2E4. \uBB34\uC5B8\uAC00\uB97C \uC9C0\uAE08 \uB2F9\uC7A5 \uC54C \uC218\uAC00 \uC5C6\uC73C\uBA70 \uAE30\uB2E4\uB824\uC57C \uD55C\uB2E4\uB294 \uAC83\uC740 \uBD84\uB178\uAC00 \uCE58\uBBF8\uB294 \uC77C\uC774 \uB418\uAE30\uB3C4 \uD55C\uB2E4."), mdx("p", null, "\uAC1C\uBC1C\uC790\uAC00 \uB418\uC9C0 \uC54A\uC740 \uB098\uC5D0 \uB300\uD574 \uC790\uC8FC \uC0DD\uAC01\uD588\uB2E4. \uCD08\uBC18\uC774 \uD798\uB4E4\uC5C8\uB358 \uC7A1\uC9C0 \uC5D0\uB514\uD130\uB85C \uACC4\uC18D \uC77C\uD558\uACE0 \uBC84\uD17C\uC73C\uBA74, \uC9C0\uAE08\uCBE4 \uC790\uC728\uAD8C\uC774 \uC0DD\uACA8\uC11C \uB354 \uC990\uAE30\uBA70 \uC4F0\uACE0\uC2F6\uC740 \uAC83 \uC4F0\uBA70 \uC0B4\uACE0 \uC788\uC5C8\uC744\uC9C0\uB3C4 \uBAA8\uB978\uB2E4. \uADF8\uB9AC\uACE0 \uADF8\uAC8C \uB354 \uD589\uBCF5\uD588\uC744\uC9C0\uB3C4 \uBAA8\uB978\uB2E4\uACE0 \uC0DD\uAC01\uD558\uBA74, \uACB0\uAD6D \uC0B6\uC758 \uC5B4\uB5A4 \uBC29\uC2DD\uACFC \uAC00\uB2A5\uC131\uC744 \uD3C9\uC0DD \uC54C\uC9C0 \uBABB\uD558\uAC8C \uB418\uC5C8\uB2E4\uB294 \uB450\uB824\uC6C0 \uD639\uC740 \uC544\uC26C\uC6C0\uC5D0 \uB2FF\uB294\uB2E4."), mdx("p", null, "\uADF8\uB3D9\uC548 \uC2A4\uC2A4\uB85C\uB97C \uD33D\uCC3D\uC2DC\uD0A4\uB294 \uBC29\uC2DD\uC73C\uB85C \uC774\uB7F0 \uB290\uB08C\uB4E4\uC5D0 \uC800\uD56D\uD588\uB2E4. \uB354 \uD589\uBCF5\uD558\uACE0 \uB354 \uB300\uB2E8\uD574\uC9C8 \uAC00\uB2A5\uC131\uC744 \uD5C8\uD22C\uB8E8 \uB118\uAE30\uC9C0 \uC54A\uACA0\uB2E4\uB294 \uD22C\uB85C."), mdx("p", null, "\uAC00\uB2A5\uC131\uB4E4\uC740 \uC774\uB7F0 \uBAA8\uC2B5\uC774\uC5C8\uB2E4. \uAC1C\uBC1C\uC790\uAC00 \uB418\uC5C8\uC73C\uB2C8 \uAE30\uC655\uC774\uBA74 \uC2E4\uB9AC\uCF58\uBC38\uB9AC\uC5D0\uC11C \uC77C\uD574\uC57C \uD558\uB294\uAC8C \uC544\uB2CC\uAC00. \uC0B4\uBA74\uC11C \uBA87\uC2ED\uC5B5 \uC815\uB3C4\uB294 \uBC8C\uC5B4\uBD10\uC57C \uD558\uB294\uAC8C \uC544\uB2CC\uAC00. \uADF8\uB7EC\uBA74 \uB354 \uC54C\uC544\uC57C \uD558\uACE0 \uB098\uB294 \uB354 \uBED7\uC5B4\uB098\uAC00\uC57C\uB9CC \uD55C\uB2E4. \uB354 \uB9CE\uC740 \uAC83\uC744 \uC774\uD574\uD558\uACE0 \uC18C\uD654\uD574\uC57C \uD55C\uB2E4. \uC0DD\uD65C\uC744 \uBE61\uBE61\uD558\uAC8C \uC720\uC9C0\uD558\uACE0 \uC870\uBC14\uC2EC\uC744 \uB0B4\uBA70 \uACC4\uD68D\uC744 \uC9DC\uB2E4\uAC00 \uBAB9\uC2DC \uC9C0\uCCD0\uBC84\uB838\uB2E4."), mdx("p", null, "\uD1F4\uADFC\uD558\uACE0 \uCE68\uB300\uC5D0 \uB098\uC790\uBE60\uC838\uC11C \uC0DD\uAC01\uD55C\uB2E4. \uBAB0\uB77C \uB450\uB824\uC6B4 \uC138\uACC4\uC640 \uB9CC\uB098\uAE30 \uC704\uD574 \uB0B4\uAC00 \uCEE4\uC9C0\uAE30\uBCF4\uB2E4, \uADF8\uB0E5 \uAC1C \uB204\uC6CC\uC788\uACE0 \uBB34\uC11C\uC6CC\uD558\uC9C0 \uC54A\uB294 \uAC83\uC740? \uB098\uC640 \uAC00\uAE4C\uC6B4 \uACF3\uC744 \uB354 \uBA74\uBC00\uD788 \uBC14\uB77C\uBCF4\uACE0 \uB354 \uC54C \uD544\uC694\uAC00 \uC788\uB294 \uAC83\uC740 \uC544\uB2CC\uC9C0."), mdx("p", null, "\uC0B6\uC774 \uBB34\uD55C\uD55C \uAC00\uB2A5\uC131\uC744 \uBCF4\uC5EC\uC8FC\uAE30\uC5D0 \uC0B6\uC5D0 \uCDE8\uD574 \uC0B4\uC558\uB358 \uAC83\uC740 \uC544\uB2CC\uC9C0."), mdx("p", null, "\uC62C\uD574\uB294 \uC791\uC740 \uBAA9\uD45C\uB9CC \uC138\uC6E0\uB2E4. \uBA40\uB9AC \uB098\uC544\uAC00\uAE30\uBCF4\uB2E4, \uB098\uB97C \uAC00\uAE4C\uC774\uC5D0\uC11C \uB458\uB7EC\uC2FC \uAC83\uB4E4\uC5D0 \uB300\uD574 \uB354 \uC54C\uACE0 \uC2F6\uB2E4. \uBB3C\uB860 \uC774\uB807\uAC8C \uB9D0\uD558\uACE0 \uC8FC 50\uC2DC\uAC04 \uB178\uB3D9\uD558\uBA70 \uC7A0 \uC880\uB354 \uB9CE\uC774 \uC790\uB294 \uC815\uB3C4\uB85C \uADF8\uCE60\uC9C0\uB294... \uBAA8\uB974\uB2C8\uAE4C \uC0AC\uB78C\uB4E4\uC774 \uC774 \uAE00\uC744 \uB300\uCDA9 \uC77D\uC5C8\uC73C\uBA74 \uC88B\uACA0\uB2E4."));
